\usepackage{amsmath,amssymb}
\usepackage[dvipsnames]{xcolor}
\usepackage{tikz}
\usepackage{pgfplots}
\pgfplotsset{
  compat=1.18,
  every axis/.append style={
    clip=true,
    clip mode=individual,
    tick label style={font=\small},
    label style={font=\small},
  }
}
\usepgfplotslibrary{fillbetween,colormaps}
\usetikzlibrary{arrows,arrows.meta,calc,decorations,decorations.markings}
\usetikzlibrary{decorations.pathreplacing,intersections,matrix,patterns}
\usetikzlibrary{positioning,shadows,shapes}

image.latex-image:
\begin{tikzpicture}[scale=0.95, every node/.style={font=\small}]
  % Speedometer: numbers sit outside the dial so the needle does not cover them.
  \draw[thick] (0,0) circle (1.35);
  \foreach \ang/\lab in {210/0,180/20,150/40,120/60,90/80,60/100,30/120} {
     \draw[thick] ({1.15*cos(\ang)},{1.15*sin(\ang)})
       -- ({1.32*cos(\ang)},{1.32*sin(\ang)});
     \node at ({1.62*cos(\ang)},{1.62*sin(\ang)}) {\lab};
  }
  \draw[very thick,->] (0,0) -- ({1.02*cos(120)},{1.02*sin(120)});
  \node at (0,-2.2) {speedometer: \(v(t)=60\) miles/hour};

  % Odometer
  \draw[rounded corners,thick] (3.6,-0.45) rectangle (6.6,0.45);
  \node[font=\ttfamily\large] at (5.1,0) {018246.3};
  \node at (5.1,-1.2) {odometer: \(d(t)\) miles};
\end{tikzpicture}

p.me:
\frac{\text{change in distance}}{\text{change in time}}
=
\frac{100\text{ miles}}{2\text{ hours}}
=
50\text{ miles/hour}.

