[L_{k+1},R_{k+1}]
=
\begin{cases}
[L_k,M_k], \amp p(L_k)\text{ and }p(M_k)\text{ have opposite signs},\\
[M_k,R_k], \amp p(M_k)\text{ and }p(R_k)\text{ have opposite signs}.
\end{cases}

