p.me:
\begin{array}{c|l}
\textbf{notation} \amp \textbf{meaning}\\
\hline
f'(x) \amp \text{the derivative function of }f\\
\dfrac{dy}{dx} \amp \text{the rate of change of }y\text{ with respect to }x\\
\dfrac{d}{dx}f(x) \amp \text{the result of differentiating }f(x)\text{ with respect to }x\\
D_x f(x) \amp \text{another compact notation for the same operation}
\end{array}

\begin{array}{c|c}
\textbf{feature of }f \amp \textbf{meaning for }f'\\
\hline
f\text{ is increasing near }x \amp f'(x)\ge0\text{, when the derivative exists}\\
f\text{ is decreasing near }x \amp f'(x)\le0\text{, when the derivative exists}\\
f\text{ has a horizontal tangent} \amp f'(x)=0\\
f\text{ is steep} \amp |f'(x)|\text{ is large}\\
f\text{ has a sharp corner} \amp f'(x)\text{ may not exist}
\end{array}

