p.me:
\begin{array}{c|c}
\textbf{quantity} \amp \textbf{relative error rule}\\
\hline
A=\pi r^2 \amp \dfrac{dA}{A}=2\dfrac{dr}{r}\\
V=\dfrac43\pi r^3 \amp \dfrac{dV}{V}=3\dfrac{dr}{r}\\
y=Cx^n \amp \dfrac{dy}{y}=n\dfrac{dx}{x}
\end{array}

