p.me:
\begin{array}{c|c|c}
\textbf{rate} \amp \textbf{integral} \amp \textbf{accumulated quantity}\\
\hline
v(t)\text{ velocity} \amp \displaystyle\int_a^b v(t)\,dt \amp \text{displacement}\\
P(t)\text{ power} \amp \displaystyle\int_a^b P(t)\,dt \amp \text{energy used}\\
r(t)\text{ population growth rate} \amp \displaystyle\int_a^b r(t)\,dt \amp \text{population change}\\
C'(q)\text{ marginal cost} \amp \displaystyle\int_a^b C'(q)\,dq \amp \text{cost increase}
\end{array}

