  \draw[fill=blue!50, draw=blue!40!black, line width=1.1pt] (0.3,0) rectangle (1.0,1.6);
  \node[above] at (0.65,1.62) {\(1\)};

  % second block
  \draw[fill=blue!50, draw=blue!40!black, line width=1.1pt] (1.2,0) rectangle (1.9,0.8);
  \node[above] at (1.55,0.82) {\(\frac12\)};

  % third block two terms
  \draw[fill=blue!50, draw=blue!40!black, line width=1.1pt] (2.3,0) rectangle (3.0,0.533);
  \draw[fill=blue!50, draw=blue!40!black, line width=1.1pt] (3.0,0) rectangle (3.7,0.4);
  \draw[decorate, decoration={brace, amplitude=6pt, raise=1pt}] (2.3,-0.12) -- (3.7,-0.12);
  \node[below] at (3.0,-0.32) {\(\ge \frac12\)};

  % fourth block four terms
  \foreach \x/\h in {4.2/0.32,4.9/0.267,5.6/0.229,6.3/0.2} {
    \draw[fill=blue!50, draw=blue!40!black, line width=1.1pt] (\x,0) rectangle +(0.7,\h);
  }
  \draw[decorate, decoration={brace, amplitude=6pt, raise=1pt}] (4.2,-0.12) -- (7.0,-0.12);
  \node[below] at (5.6,-0.32) {\(\ge \frac12\)};

  % fifth block eight stylized terms at common lower height
  \foreach \i in {0,...,7} {
    \draw[fill=blue!50, draw=blue!40!black, line width=1.1pt] ({7.7+0.55*\i},0) rectangle +(0.55,0.2);
  }
  \draw[decorate, decoration={brace, amplitude=6pt, raise=1pt}] (7.7,-0.12) -- (12.1,-0.12);
  \node[below] at (9.9,-0.32) {\(\ge \frac12\)};

  \node[align=center] at (7.4,1.45) {each new doubled block\\adds at least \(\frac12\)};
\end{tikzpicture}

